/* Local DXF editor. Material coordinates remain unchanged by display orientation. */
const $ = id => document.getElementById(id);
const NS = 'http://www.w3.org/2000/svg';
const clone = value => JSON.parse(JSON.stringify(value));
const state = { drawing:null, project:null, revision:0, saved:'', selected:new Set(), draft:null, draftBase:'', current:null, statuses:{}, statistics:{}, geometries:{}, regions:[], preview:null, tool:'select', orientation:'270', view:null, fitWidth:1, hovered:null, history:[], redo:[], busy:false, previewSerial:0, localChanges:false };
const paths = new Map();
let featureTypes = [];
let segments = new Map(), drag = null, spaceDown = false, toastTimer, previewTimer, validateTimer, lastHit = null;

function element(tag, attrs={}) { const e=document.createElementNS(NS,tag); for(const [k,v] of Object.entries(attrs)) e.setAttribute(k,v); return e; }
function textElement(tag, value, className='') { const e=document.createElement(tag); e.textContent=value; if(className)e.className=className; return e; }
function toast(message,error=false) { const e=$('toast'); e.textContent=message;e.classList.toggle('error',error);e.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.hidden=true,error?6500:3800); }
async function request(url, data) { const r=await fetch(url,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}); let body;try{body=await r.json();}catch{throw new Error(`服务返回异常（${r.status}）`);} if(!r.ok)throw new Error(body.message||body.error||`请求失败（${r.status}）`);return body; }

function ask(message,options={}) {
  return new Promise(resolve=>{
    const previousFocus=document.activeElement;
    const cover=textElement('div','','editor-dialog-cover'),box=textElement('div','','editor-dialog');
    box.setAttribute('role','dialog');box.setAttribute('aria-modal','true');box.setAttribute('aria-label',message);
    box.append(textElement('p',message));let input=null;
    if(options.input){input=document.createElement('input');input.value=options.initial||'';input.setAttribute('aria-label','原因');box.append(input);}
    const buttons=textElement('div','','inline-actions'),cancel=textElement('button','取消'),accept=textElement('button','确定','primary');
    let settled=false;
    const finish=value=>{if(settled)return;settled=true;cover.remove();previousFocus?.focus?.();resolve(value);};cancel.type='button';accept.type='button';cancel.onclick=()=>finish(options.input?null:false);accept.onclick=()=>finish(options.input?input.value:true);
    buttons.append(cancel,accept);box.append(buttons);cover.append(box);document.body.append(cover);(input||cancel).focus();
    cover.addEventListener('keydown',event=>{
      event.stopPropagation();
      if(event.key==='Escape'){event.preventDefault();finish(options.input?null:false);}
      else if(event.key==='Enter'&&options.input&&event.target===input){event.preventDefault();finish(input.value);}
      else if(event.key==='Tab'){
        const focusable=input?[input,cancel,accept]:[cancel,accept];
        const current=focusable.indexOf(document.activeElement);
        if((event.shiftKey&&current<=0)||(!event.shiftKey&&current===focusable.length-1)){event.preventDefault();focusable[event.shiftKey?focusable.length-1:0].focus();}
      }
    });
  });
}

function fingerprint(){return JSON.stringify(state.project);}
function hasDraftChanges(){return !!state.draft&&JSON.stringify(state.draft)!==state.draftBase;}
function isDirty(){return state.project&&(fingerprint()!==state.saved||hasDraftChanges());}
function updateDirty(){const dirty=isDirty();$('save-status').textContent=dirty?'有未保存修改':`已保存 · 修订 ${state.revision}`;$('save-status').classList.toggle('dirty',!!dirty);$('undo').disabled=!state.history.length;$('redo').disabled=!state.redo.length;$('draft-state').textContent=hasDraftChanges()?(state.current?`正在修改 ${state.draft.operation_id}；本次选择尚未应用。录下一动作请点“＋新建”，放弃误加的选择。`:'新动作尚未创建；点击“创建动作，录下一个”后会清空选择。'):(state.current?`当前修改会作用于 ${state.draft.operation_id}；录下一动作请先点“＋新建”。`:'选取图元并填写新动作；创建后自动清空选择，进入下一动作。');}
function snapshot(){return {project:clone(state.project),draft:clone(state.draft),current:state.current,selected:[...state.selected],draftBase:state.draftBase};}
function checkpoint(){state.history.push(snapshot());if(state.history.length>70)state.history.shift();state.redo=[];}
function restore(s){state.project=s.project;state.project.revision=state.revision;state.draft=s.draft;state.current=s.current;state.selected=new Set(s.selected);state.draftBase=s.draftBase;state.preview=null;renderProject();scheduleValidate();schedulePreview();}
function undo(){if(!state.history.length)return;state.redo.push(snapshot());restore(state.history.pop());}
function redo(){if(!state.redo.length)return;state.history.push(snapshot());restore(state.redo.pop());}
function defaultOperation(){return {uid:crypto.randomUUID(),operation_id:'',name:'',operation_type:'',feature_type:'',geometry_shape:'',bend_angle_deg:null,surface_side:'NOT_APPLICABLE',cad_parent_operation_id:null,required_predecessor_ids:[],process_group_id:null,source_segment_ids:[],shared_source_segment_ids:[],geometry_options:{confirmed_span:false,confirmed_footprint:false,start_segment_id:null},bend_source_is_centerline:false,no_geometry:false,no_geometry_reason:'',region:null,absorb_interior:true,absorption_exclusions:[],notes:'',protrusion_side:'UNKNOWN'};}

async function discardDraft(){return !hasDraftChanges()||await ask('当前动作有未应用修改。放弃这些修改并切换？');}
function setDraft(operation){state.formBefore=null;state.draft=clone(operation);state.draft.geometry_options={confirmed_span:false,confirmed_footprint:false,...state.draft.geometry_options,start_segment_id:state.draft.geometry_options?.start_segment_id||null};state.current=state.project.operations.some(o=>o.uid===operation.uid)?operation.uid:null;state.selected=new Set(operation.source_segment_ids||[]);state.draftBase=JSON.stringify(state.draft);state.preview=null;renderEditor();renderList();renderSelection();schedulePreview();updateDirty();}
async function newOperation(){if(!await discardDraft())return;checkpoint();setDraft(defaultOperation());}
function invalidateGeometry(){if(!state.draft)return;state.draft.geometry_options={...state.draft.geometry_options,confirmed_span:false,confirmed_footprint:false};if(state.draft.region)state.draft.region.confirmed=false;}
function setSelection(ids, additive=false, toggle=false){state.formBefore=null;checkpoint();const next=additive?new Set(state.selected):new Set();for(const id of ids){if(toggle&&next.has(id))next.delete(id);else next.add(id);}state.selected=next;state.draft.source_segment_ids=[...next];invalidateGeometry();state.preview=null;renderEditor();renderSelection();schedulePreview();updateDirty();}

function splitIds(value){return [...new Set(value.split(/[,，;；\s]+/).map(v=>v.trim()).filter(Boolean))];}
function readForm(){
  const op=state.draft,previousType=op.operation_type;op.operation_id=$('operation-id').value.trim();op.name=$('operation-name').value.trim();op.feature_type=$('operation-type').value;const type=featureTypes.find(t=>t.key===op.feature_type);op.operation_type=type?.operation_type||'';op.geometry_shape=type?.shape||'';op.surface_side=$('surface-side').value;op.cad_parent_operation_id=$('cad-parent').value.trim()||null;op.required_predecessor_ids=splitIds($('predecessors').value);op.process_group_id=$('process-group').value.trim()||null;
  if(op.operation_type==='BEND'){const value=$('bend-angle').value;if(previousType!=='BEND'){op.bend_angle_deg=state.fieldDefaults?.bend_angle_deg??null;$('bend-angle').value=op.bend_angle_deg??'';}else op.bend_angle_deg=value===''?null:Number(value);}else op.bend_angle_deg=null;
  op.no_geometry=$('no-geometry').checked;op.no_geometry_reason=$('no-geometry-reason').value.trim();op.bend_source_is_centerline=$('bend-source-centerline').checked;op.notes=$('operation-notes').value;op.protrusion_side=$('protrusion-side').value;op.geometry_options={...op.geometry_options,confirmed_span:$('span-confirmed').checked,confirmed_footprint:$('footprint-confirmed').checked};op.absorb_interior=$('absorb-interior').checked;
  if(op.feature_type==='BEND_STRAIGHT'){op.region=$('region-enabled').checked?{...op.region,influence_region_id:$('region-id').value.trim(),affected_side:$('affected-side').value,far_boundary_coord:$('far-boundary').value===''?null:Number($('far-boundary').value),parent_region_id:$('parent-region').value||null,parent_confirmed:$('parent-confirmed').checked,confirmed:$('region-confirmed').checked}:null;}else if(op.operation_type!=='BEND')op.region=null;
  return op;
}

function applyOperation(showMessage=true,{advanceAfterCreate=false}={}){
  if(state.current&&!hasDraftChanges()){if(showMessage)toast('当前动作标注未变化。');return true;}
  readForm();const op=state.draft;
  if(!op.operation_id||!op.name||!op.operation_type){toast('请填写动作编号、名称和类型。',true);return false;}
  if(state.project.operations.some(o=>o.uid!==op.uid&&o.operation_id===op.operation_id)){toast(`动作编号 ${op.operation_id} 已存在。`,true);return false;}
  const shared=op.source_segment_ids.filter(id=>state.project.operations.some(o=>o.uid!==op.uid&&(o.source_segment_ids||[]).includes(id)));
  if(shared.length&&!$('shared-confirmed').checked){toast('所选图元已属于其它动作，请确认共用或取消误选。',true);return false;}
  checkpoint();const index=state.project.operations.findIndex(o=>o.uid===op.uid),old=index<0?null:state.project.operations[index];
  if(index<0)state.history[state.history.length-1].draftBase=JSON.stringify(state.draft);
  op.shared_source_segment_ids=shared;
  for(const item of state.project.operations){const ids=(item.source_segment_ids||[]).filter(id=>shared.includes(id));if(ids.length)item.shared_source_segment_ids=[...new Set([...(item.shared_source_segment_ids||[]),...ids])];}
  delete state.project.geometry_batch;state.geometries={};state.geometryRecords={};state.regions=[];state.geometryState='NOT_COMPILED_OR_STALE';
  if(old&&(old.feature_type!==op.feature_type||JSON.stringify(old.source_segment_ids)!==JSON.stringify(op.source_segment_ids)))state.project.inventory_confirmed=false;
  if(old&&old.operation_id!==op.operation_id){for(const fixed of state.project.fixed_rows||[]){if(fixed.operation_id===old.operation_id)fixed.operation_id=op.operation_id;}for(const item of state.project.operations){if(item.cad_parent_operation_id===old.operation_id)item.cad_parent_operation_id=op.operation_id;item.required_predecessor_ids=(item.required_predecessor_ids||[]).map(id=>id===old.operation_id?op.operation_id:id);}if(op.cad_parent_operation_id===old.operation_id)op.cad_parent_operation_id=op.operation_id;op.required_predecessor_ids=(op.required_predecessor_ids||[]).map(id=>id===old.operation_id?op.operation_id:id);}
  if(index<0){state.project.operations.push(clone(op));state.project.inventory_confirmed=false;}else state.project.operations[index]=clone(op);
  if(index<0&&advanceAfterCreate){setDraft(defaultOperation());}else{state.current=op.uid;state.draftBase=JSON.stringify(op);state.preview=null;}
  renderProject();if(index<0)$('operation-list').scrollTop=0;scheduleValidate();schedulePreview();if(showMessage)toast(index<0&&advanceAfterCreate?`${op.operation_id} 已创建；已清空选择，可录入下一动作。请保存标注以写入文件。`:`${op.operation_id} 已${index<0?'创建':'应用修改'}；保存标注后写入项目文件。`);return true;
}
function deleteOperation(){if(!state.current)return;const op=state.project.operations.find(o=>o.uid===state.current);checkpoint();state.project.operations=state.project.operations.filter(o=>o.uid!==state.current);state.project.inventory_confirmed=false;state.current=null;state.draft=defaultOperation();state.selected.clear();state.draftBase=JSON.stringify(state.draft);state.preview=null;renderProject();scheduleValidate();}

function renderEditor(){
  const op=state.draft;if(!op)return;$('editor-title').textContent=state.current?`编辑 ${op.operation_id}`:'新建加工动作';$('editor-context').textContent=state.current?`正在修改 ${op.operation_id}；添加其他动作请先点“＋新建”。`:'选取图元并填写属性，创建后自动进入下一动作。';$('operation-id').value=op.operation_id||'';$('operation-name').value=op.name||'';$('operation-type').value=op.feature_type||'';$('surface-side').value=op.surface_side??'NOT_APPLICABLE';if($('cad-parent').value!==(op.cad_parent_operation_id||''))$('cad-parent').value=op.cad_parent_operation_id||'';$('predecessors').value=(op.required_predecessor_ids||[]).join(', ');$('process-group').value=op.process_group_id||'';renderPairingHint();
  $('span-confirmed').checked=!!op.geometry_options?.confirmed_span;$('footprint-confirmed').checked=!!op.geometry_options?.confirmed_footprint;$('absorb-interior').checked=op.absorb_interior!==false;$('no-geometry').checked=!!op.no_geometry;$('no-geometry-reason').value=op.no_geometry_reason||'';$('bend-source-centerline').checked=!!op.bend_source_is_centerline;$('operation-notes').value=op.notes||'';$('protrusion-side').value=op.protrusion_side||'UNKNOWN';
  $('bend-angle-row').hidden=op.operation_type!=='BEND';$('bend-angle').value=op.bend_angle_deg??'';
  const straight=op.feature_type==='BEND_STRAIGHT';$('centerline-row').hidden=!straight;$('span-confirm-row').hidden=!straight;$('footprint-confirm-row').hidden=op.operation_type!=='BRIDGE';$('absorb-row').hidden=op.operation_type!=='BRIDGE';$('no-geometry-row').hidden=!op.no_geometry;$('protrusion-row').hidden=op.operation_type!=='DRAW_FORM';$('region-editor').hidden=!straight;$('region-enabled').checked=!!op.region;$('region-fields').hidden=!op.region;
  $('geometry-help').textContent=op.feature_type==='BEND_CURVED'?'曲线折弯：完整保留选中线形；几何与影响区规则待确认。':op.operation_type==='DRAW_FORM'?'拉包允许内外多组闭合轮廓；不会自动推断顶部/底部，也不会吸收内部独立孔。':'先保存动作标注；整图解释完成后按类型统一整理几何。';
  const shared=[...state.selected].flatMap(id=>state.project.operations.filter(o=>o.uid!==op.uid&&(o.source_segment_ids||[]).includes(id)).map(o=>o.operation_id));$('binding-warning').hidden=!shared.length;$('binding-warning').textContent=shared.length?`部分图元已绑定 ${[...new Set(shared)].join('、')}。若确需共用，请勾选下方确认。`:'';$('shared-row').hidden=!shared.length;$('shared-confirmed').checked=shared.length>0&&[...state.selected].filter(id=>state.project.operations.some(o=>o.uid!==op.uid&&(o.source_segment_ids||[]).includes(id))).every(id=>(op.shared_source_segment_ids||[]).includes(id));
  updateOperationOptions();
  const parent=$('parent-region');parent.replaceChildren(new Option('无父级 / 尚未确认',''));for(const item of state.project.operations){if(item.uid!==op.uid&&item.region?.influence_region_id)parent.add(new Option(`${item.region.influence_region_id} · ${item.operation_id}`,item.region.influence_region_id));}if(op.region?.parent_region_id&&!Array.from(parent.options).some(o=>o.value===op.region.parent_region_id))parent.add(new Option(`${op.region.parent_region_id}（尚不存在）`,op.region.parent_region_id));
  $('region-id').value=op.region?.influence_region_id||'';$('affected-side').value=op.region?.affected_side||'';$('far-boundary').value=op.region?.far_boundary_coord??'';parent.value=op.region?.parent_region_id||'';$('parent-confirmed').checked=!!op.region?.parent_confirmed;$('region-confirmed').checked=!!op.region?.confirmed;$('apply-operation').textContent=state.current?'应用标注修改':'创建动作，录下一个';$('delete-operation').hidden=!state.current;$('draft-selection-count').textContent=selectionSummary();
}

function updateOperationOptions(){const key=JSON.stringify(state.project.operations.map(op=>[op.operation_id,op.name]));if(state.operationOptionsKey===key)return;const options=$('operation-options');options.replaceChildren();for(const item of state.project.operations){const option=document.createElement('option');option.value=item.operation_id;option.label=item.name;options.append(option);}state.operationOptionsKey=key;}
function cadParentOperation(){const matches=state.project.operations.filter(op=>op.operation_id===state.draft?.cad_parent_operation_id&&op.uid!==state.draft?.uid);return matches.length===1?matches[0]:null;}
function parentSourceIds(){return new Set(cadParentOperation()?.source_segment_ids||[]);}
function focusCanvasForSelection(){$('drawing').focus({preventScroll:true});}

function selectionSummary(){const applied=state.project.operations.find(op=>op.uid===state.current);return applied?`本次已选 ${state.selected.size} 个来源片段 · ${applied.operation_id} 已应用绑定 ${(applied.source_segment_ids||[]).length} 个`:`新动作：本次已选 ${state.selected.size} 个来源片段`;}

function renderList(){const list=$('operation-list'),scrollTop=list.scrollTop||0,query=$('operation-search').value.trim().toLowerCase(),type=$('operation-filter').value;list.replaceChildren();let count=0;for(const op of [...state.project.operations].reverse()){if(type&&op.feature_type!==type)continue;if(query&&!`${op.operation_id} ${op.name} ${op.operation_type}`.toLowerCase().includes(query))continue;count++;const item=textElement('div','','operation-item');item.classList.toggle('current',op.uid===state.current);item.tabIndex=0;item.setAttribute('role','listitem');item.dataset.uid=op.uid;const title=textElement('div','','operation-title');title.append(textElement('strong',op.operation_id||'未编号'),textElement('span',featureTypes.find(t=>t.key===op.feature_type)?.label||op.operation_type||'未分类','operation-type'));item.append(title,textElement('div',op.name||'未命名','operation-name'));if(op.cad_parent_operation_id)item.append(textElement('div',`父动作 ${op.cad_parent_operation_id}`,'operation-parent'));const open=async()=>{if(await discardDraft())setDraft(op);};item.addEventListener('click',open);item.addEventListener('keydown',e=>{if(e.key==='Enter')open();});list.append(item);}if(!count)list.append(textElement('div',state.project.operations.length?'没有匹配的动作':'从图中选择几何，创建第一个动作。\n尚未自动导入任何参考答案。','empty-list'));$('operation-count').textContent=state.project.operations.length;list.scrollTop=scrollTop;}
function renderStatistics(){$('workflow-state').textContent=state.geometryState==='CURRENT'?'② 已整理几何 · 检查待确认项后导出':state.project.inventory_confirmed?'① 整图已确认 · 点击整理几何':'① 逐个解释动作并绑定图元';const s=state.statistics||{},items=[['全部片段',s.total??segments.size],['直接绑定',s.bound??0],['区域收纳',s.absorbed??0],['背景 / 忽略',s.ignored??0],['尚未处理',s.unhandled??segments.size],['不支持实体',s.unsupported??0]],container=$('statistics');container.replaceChildren();for(const [label,value] of items){const row=textElement('div','',`stat-line${label==='尚未处理'?' unhandled':''}`);row.append(textElement('span',label),textElement('b',String(value)));container.append(row);}$('configuration-state').textContent=`Sheet3：${state.project.station_rows?.length||0} 个工序 · Sheet4：${state.project.sheet4_confirmed?'已确认':'待填写 / 确认'}`;}
function renderProject(){$('part-id').value=state.project.part_id||'P001';$('expected-count').value=state.project.expected_operation_count??'';$('inventory-confirmed').checked=!!state.project.inventory_confirmed;renderList();renderEditor();renderSelection();renderStatistics();updateDirty();}

function number(s,...keys){for(const key of keys){if(s[key]!==undefined&&s[key]!==null)return Number(s[key]);}return 0;}
function start(s){return [number(s,'start_x','x1'),number(s,'start_y','y1')];}
function end(s){return [number(s,'end_x','x2'),number(s,'end_y','y2')];}
function center(s){return [number(s,'center_x','cx'),number(s,'center_y','cy')];}
function sweep(s){return number(s,'sweep_angle','sweep_angle_deg','sweep');}
function kind(s){return String(s.segment_type||s.type||'LINE').toUpperCase();}
function pathData(s){const a=start(s),b=end(s),c=center(s),r=number(s,'radius','r'),type=kind(s);if(type==='CIRCLE')return `M ${c[0]+r} ${c[1]} A ${r} ${r} 0 1 1 ${c[0]-r} ${c[1]} A ${r} ${r} 0 1 1 ${c[0]+r} ${c[1]}`;if(type==='ARC'){const sw=sweep(s);return `M ${a[0]} ${a[1]} A ${r} ${r} 0 ${Math.abs(sw)>180?1:0} ${sw>=0?1:0} ${b[0]} ${b[1]}`;}if(type==='BRIDGE'||type==='RECTANGLE')return `M ${a[0]} ${a[1]} H ${b[0]} V ${b[1]} H ${a[0]} Z`;return `M ${a[0]} ${a[1]} L ${b[0]} ${b[1]}`;}
function bbox(s){if(Array.isArray(s.bbox))return s.bbox;if(s.bbox&&typeof s.bbox==='object')return [s.bbox.min_x??s.bbox.x_min,s.bbox.min_y??s.bbox.y_min,s.bbox.max_x??s.bbox.x_max,s.bbox.max_y??s.bbox.y_max];const a=start(s),b=end(s),c=center(s),r=number(s,'radius','r');if(['CIRCLE','ARC'].includes(kind(s)))return [c[0]-r,c[1]-r,c[0]+r,c[1]+r];return [Math.min(a[0],b[0]),Math.min(a[1],b[1]),Math.max(a[0],b[0]),Math.max(a[1],b[1])];}
function display(p){return state.orientation==='270'?[p[1],p[0]]:[p[0],-p[1]];}
function material(p){return state.orientation==='270'?[p[1],p[0]]:[p[0],-p[1]];}
function setTransform(){$('material-layer').setAttribute('transform',state.orientation==='270'?'matrix(0 1 1 0 0 0)':'matrix(1 0 0 -1 0 0)');renderAnnotations();}
function annotationTransform(a){const p=display([a.x,a.y]),angle=state.orientation==='270'?90-a.rotation:-a.rotation;return `translate(${p[0]} ${p[1]}) rotate(${angle}) scale(${a.width_factor||1} 1)`;}
function annotationInk(color){return ({1:'#b83337',2:'#846500',3:'#287343',4:'#087e93',5:'#326ca8'})[color]||'#566477';}
function renderAnnotations(){const layer=$('annotation-layer'),toggle=$('show-annotations'),annotations=state.drawing.annotations||[];toggle.disabled=!annotations.length;if(!annotations.length)toggle.checked=false;layer.replaceChildren();layer.style.display=$('show-annotations').checked?'':'none';for(const a of annotations){if(a.is_visible===false)continue;const t=element('text',{transform:annotationTransform(a),'font-size':a.height,fill:annotationInk(a.color),'dominant-baseline':a.baseline||'alphabetic'});t.textContent=a.text;layer.append(t);}}

function applyView(){if(!state.view)return;$('drawing').setAttribute('viewBox',state.view.join(' '));$('zoom-status').textContent=`${Math.round(state.fitWidth/state.view[2]*100)}%`;}
function drawingBounds(){let b=state.drawing.bounds;if(Array.isArray(b))return b;if(b&&typeof b==='object')return [b.min_x??b.x_min,b.min_y??b.y_min,b.max_x??b.x_max,b.max_y??b.y_max];return union([...segments.values()].map(bbox));}
function union(boxes){if(!boxes.length)return [0,0,1,1];return [Math.min(...boxes.map(b=>b[0])),Math.min(...boxes.map(b=>b[1])),Math.max(...boxes.map(b=>b[2])),Math.max(...boxes.map(b=>b[3]))];}
function fitBounds(b,all=false){const a=display([b[0],b[1]]),c=display([b[2],b[3]]),rect=$('drawing').getBoundingClientRect(),ratio=rect.width/Math.max(rect.height,1);let w=Math.max(Math.abs(c[0]-a[0]),1)*1.15,h=Math.max(Math.abs(c[1]-a[1]),1)*1.15;if(w/h<ratio)w=h*ratio;else h=w/ratio;state.view=[(a[0]+c[0])/2-w/2,(a[1]+c[1])/2-h/2,w,h];if(all)state.fitWidth=w;applyView();}
function fitAll(){fitBounds(drawingBounds(),true);}
function fitCurrent(){const ids=state.selected.size?[...state.selected]:state.draft?.source_segment_ids||[],boxes=ids.map(id=>segments.get(id)).filter(Boolean).map(bbox);if(!boxes.length){toast('当前动作尚无可聚焦的几何。');return;}fitBounds(union(boxes));}
function screenToDisplay(clientX,clientY){const svg=$('drawing'),p=svg.createSVGPoint();p.x=clientX;p.y=clientY;const inv=svg.getScreenCTM()?.inverse();if(!inv)return [0,0];const q=p.matrixTransform(inv);return [q.x,q.y];}
function screenToMaterial(x,y){return material(screenToDisplay(x,y));}
function pixelScale(){return state.view?state.view[2]/Math.max(1,$('drawing').getBoundingClientRect().width):1;}
function initializeDrawing(){segments=new Map(state.drawing.segments.map(s=>[s.id,s]));paths.clear();const frag=document.createDocumentFragment();for(const s of segments.values()){const p=element('path',{d:pathData(s),'data-id':s.id});if(/DASH|HIDDEN|CENTER/i.test(s.linetype||''))p.setAttribute('stroke-dasharray','6 3');paths.set(s.id,p);frag.append(p);}$('source-layer').replaceChildren(frag);setTransform();$('empty-canvas').hidden=segments.size>0;if(!segments.size)$('empty-canvas').textContent='没有可显示的几何，请查看解析报告。';fitAll();renderSelection();}
function renderSelection(){const active=new Set(state.current?(state.project.operations.find(o=>o.uid===state.current)?.source_segment_ids||[]):[]),parent=cadParentOperation(),parentSources=parentSourceIds();for(const [id,p]of paths){const classes=[state.statuses[id]||'unhandled'];if(active.has(id))classes.push('current');if(parentSources.has(id))classes.push('cad-parent');if(state.selected.has(id))classes.push('selected');if(state.hovered===id)classes.push('hovered');p.setAttribute('class',classes.join(' '));}raiseSelectedSourcePaths();$('parent-highlight-status').hidden=!parentSources.size;$('parent-highlight-status').textContent=parentSources.size?`父动作 ${parent.operation_id} · 蓝色`:'';$('selection-status').textContent=`已选 ${state.selected.size} 个片段${state.current?` · 当前 ${state.draft.operation_id}`:''}`;$('draft-selection-count').textContent=selectionSummary();renderEntityDetails();renderOverlays();}
function raiseSelectedSourcePaths(){
  // DXF entities may coincide. Move existing selected paths above neutral copies
  // without merging source IDs or changing hit-test order / annotation bindings.
  const layer=$('source-layer');for(const [id,path]of paths){if(state.selected.has(id))layer.append(path);}
}

function renderEntityDetails(){const box=$('entity-details');box.replaceChildren();const ids=[...state.selected];if(!ids.length){box.textContent='点选图元可查看精确材料坐标和来源。';return;}for(const id of ids.slice(-5).reverse()){const s=segments.get(id);if(!s)continue;box.append(textElement('div',`${kind(s)} · ${id}`,'entity-id'));const dl=document.createElement('dl'),props=[['来源',s.source_group||s.source_handle||'—'],['图层',s.layer||'—'],['状态',({bound:'直接绑定',absorbed:'区域收纳',ignored:'背景 / 忽略',unhandled:'尚未处理'})[state.statuses[id]||'unhandled']]];if(kind(s)==='CIRCLE')props.push(['圆心',center(s).map(v=>v.toPrecision(9)).join(', ')],['半径',String(number(s,'radius','r'))]);else props.push(['起点',start(s).map(v=>v.toPrecision(9)).join(', ')],['终点',end(s).map(v=>v.toPrecision(9)).join(', ')]);if(kind(s)==='ARC')props.push(['扫角',`${sweep(s)}°`]);for(const [k,v]of props){dl.append(textElement('dt',k),textElement('dd',v));}box.append(dl);}if(ids.length>5)box.append(textElement('p',`另有 ${ids.length-5} 个已选片段。`));}
function regionBox(region){if(region.bbox)return region.bbox;if(region.rectangle)return region.rectangle;const a=[Number(region.start_x),Number(region.start_y)],b=[Number(region.end_x),Number(region.end_y)],far=Number(region.far_boundary_coord);if(!Number.isFinite(far))return null;if(String(region.bend_axis).toUpperCase()==='X'||Math.abs(a[1]-b[1])<1e-6)return [Math.min(a[0],b[0]),Math.min(a[1],far),Math.max(a[0],b[0]),Math.max(a[1],far)];return [Math.min(a[0],far),Math.min(a[1],b[1]),Math.max(a[0],far),Math.max(a[1],b[1])];}
function renderOverlays(){const geo=$('geometry-layer'),regions=$('region-layer');geo.replaceChildren();regions.replaceChildren();if(state.current&&!state.preview&&!hasDraftChanges()){for(const s of (state.geometryRecords?.[state.current]?.paths||[]).flatMap(p=>p.segments).length?(state.geometryRecords[state.current].paths.flatMap(p=>p.segments)):(state.geometries[state.current]||[]))geo.append(element('path',{d:pathData(s)}));}if(state.preview){for(const s of state.preview.geometry||[])geo.append(element('path',{d:pathData(s),class:'preview'}));}if(!$('show-regions').checked)return;const list=[...state.regions];if(state.preview?.region)list.push({...state.preview.region,__preview:true});for(const r of list){if((r.operation_uid===state.current||r.bend_operation_id===state.draft?.operation_id)&&state.preview?.region&&!r.__preview)continue;const b=regionBox(r);if(!b||!b.every(Number.isFinite))continue;regions.append(element('rect',{x:b[0],y:b[1],width:b[2]-b[0],height:b[3]-b[1],class:r.__preview?'preview-region':''}));}}

function lineDistance(p,a,b){const vx=b[0]-a[0],vy=b[1]-a[1],den=vx*vx+vy*vy;const t=den?Math.max(0,Math.min(1,((p[0]-a[0])*vx+(p[1]-a[1])*vy)/den)):0;return Math.hypot(p[0]-a[0]-t*vx,p[1]-a[1]-t*vy);}
function angleOnArc(angle,startAngle,sw){const tau=Math.PI*2,positive=v=>(v%tau+tau)%tau;return sw>=0?positive(angle-startAngle)<=sw*Math.PI/180+1e-8:positive(startAngle-angle)<=-sw*Math.PI/180+1e-8;}
function distance(p,s){const type=kind(s);if(type==='LINE'||type==='BEND_LINE')return lineDistance(p,start(s),end(s));if(['CIRCLE','ARC'].includes(type)){const c=center(s),r=number(s,'radius','r'),a=start(s);if(type==='CIRCLE'||angleOnArc(Math.atan2(p[1]-c[1],p[0]-c[0]),Math.atan2(a[1]-c[1],a[0]-c[0]),sweep(s)))return Math.abs(Math.hypot(p[0]-c[0],p[1]-c[1])-r);return Math.min(Math.hypot(p[0]-a[0],p[1]-a[1]),Math.hypot(p[0]-end(s)[0],p[1]-end(s)[1]));}const b=bbox(s);return Math.min(lineDistance(p,[b[0],b[1]],[b[2],b[1]]),lineDistance(p,[b[2],b[1]],[b[2],b[3]]),lineDistance(p,[b[2],b[3]],[b[0],b[3]]),lineDistance(p,[b[0],b[3]],[b[0],b[1]]));}
function nearby(p){const tolerance=(state.drawing.config?.hit_tolerance_px||7)*pixelScale(),result=[];for(const s of segments.values()){if(!$('show-background').checked&&state.statuses[s.id]==='ignored')continue;const b=bbox(s);if(p[0]<b[0]-tolerance||p[0]>b[2]+tolerance||p[1]<b[1]-tolerance||p[1]>b[3]+tolerance)continue;const d=distance(p,s);if(d<=tolerance)result.push({id:s.id,d});}return result.sort((a,b)=>a.d-b.d);}
function showHitPicker(hits,event){const box=$('hit-picker');box.replaceChildren(textElement('p',`${hits.length} 个相近实体，选择其一`));for(const h of hits.slice(0,20)){const s=segments.get(h.id),button=textElement('button',`${kind(s)} · ${h.id}`);button.type='button';button.addEventListener('click',()=>{setSelection([h.id],true,true);box.hidden=true;});box.append(button);}const r=$('canvas-wrap').getBoundingClientRect();box.style.left=`${Math.min(event.clientX-r.left,r.width-230)}px`;box.style.top=`${Math.min(event.clientY-r.top,r.height-190)}px`;box.hidden=false;}
function clickCanvas(e){const p=screenToMaterial(e.clientX,e.clientY),hits=nearby(p);if(!hits.length){return;}if(hits.length>1&&!e.altKey){showHitPicker(hits,e);return;}let index=0;if(e.altKey&&lastHit&&Math.hypot(e.clientX-lastHit.x,e.clientY-lastHit.y)<8)index=(lastHit.index+1)%hits.length;lastHit={x:e.clientX,y:e.clientY,index};setSelection([hits[index].id],true,true);}
function boxSelect(a,b,add){const p=material(a),q=material(b),rect=[Math.min(p[0],q[0]),Math.min(p[1],q[1]),Math.max(p[0],q[0]),Math.max(p[1],q[1])],eps=pixelScale()*.5,ids=[];for(const s of segments.values()){const r=bbox(s);if(r[0]>=rect[0]-eps&&r[1]>=rect[1]-eps&&r[2]<=rect[2]+eps&&r[3]<=rect[3]+eps)ids.push(s.id);}setSelection(ids,true);toast(`框选 ${ids.length} 个完整位于框内的实体。`);}
function initializeCanvasEvents(){const svg=$('drawing');svg.addEventListener('contextmenu',e=>e.preventDefault());svg.addEventListener('pointerdown',e=>{if(e.button===2)return;focusCanvasForSelection();$('hit-picker').hidden=true;const pan=e.button===1||spaceDown||state.tool==='pan';drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,start:screenToDisplay(e.clientX,e.clientY),pan,box:!pan&&state.tool==='box',shift:e.shiftKey,moved:false};svg.setPointerCapture(e.pointerId);if(pan)svg.classList.add('dragging');e.preventDefault();});svg.addEventListener('pointermove',e=>{const p=screenToMaterial(e.clientX,e.clientY);$('coordinate-status').textContent=`材料 X ${p[0].toFixed(3)} · Y ${p[1].toFixed(3)}`;if(drag){const d=screenToDisplay(e.clientX,e.clientY);drag.moved ||= Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>3;if(drag.pan){const last=screenToDisplay(drag.lastX,drag.lastY);state.view[0]-=d[0]-last[0];state.view[1]-=d[1]-last[1];applyView();}else if(drag.box){const a=drag.start,r=$('selection-box');r.removeAttribute('hidden');r.setAttribute('x',Math.min(a[0],d[0]));r.setAttribute('y',Math.min(a[1],d[1]));r.setAttribute('width',Math.abs(a[0]-d[0]));r.setAttribute('height',Math.abs(a[1]-d[1]));}drag.lastX=e.clientX;drag.lastY=e.clientY;return;}const h=nearby(p)[0]?.id||null;if(h!==state.hovered){const old=state.hovered;state.hovered=h;if(old)paths.get(old)?.classList.remove('hovered');if(h)paths.get(h)?.classList.add('hovered');}});svg.addEventListener('pointerup',e=>{if(!drag)return;const ended=drag;drag=null;svg.classList.remove('dragging');$('selection-box').setAttribute('hidden','');if(ended.box&&ended.moved)boxSelect(ended.start,screenToDisplay(e.clientX,e.clientY),ended.shift);else if(!ended.pan&&!ended.moved)clickCanvas(e);});svg.addEventListener('pointercancel',()=>{drag=null;$('selection-box').setAttribute('hidden','');svg.classList.remove('dragging');});svg.addEventListener('pointerleave',()=>{if(!drag&&state.hovered){paths.get(state.hovered)?.classList.remove('hovered');state.hovered=null;}});svg.addEventListener('wheel',e=>{e.preventDefault();if(!state.view)return;const p=screenToDisplay(e.clientX,e.clientY),factor=Math.exp(Math.max(-1,Math.min(1,e.deltaY/350))),w=state.view[2]*factor;if(w<state.fitWidth/5000||w>state.fitWidth*30)return;state.view=[p[0]+(state.view[0]-p[0])*factor,p[1]+(state.view[1]-p[1])*factor,w,state.view[3]*factor];applyView();},{passive:false});}

function temporaryProject(){const p=clone(state.project);if(state.draft){const i=p.operations.findIndex(o=>o.uid===state.draft.uid);if(i<0)p.operations.push(clone(state.draft));else p.operations[i]=clone(state.draft);}return p;}
function issueMessage(i){if(typeof i==='string')return i;return [i.code||i.type||i.constraint_type,i.operation_id||'',i.message||i.detail||JSON.stringify(i)].filter(Boolean).join(' · ');}
function renderIssues(container,issues,limit=100){container.replaceChildren();for(const i of (issues||[]).slice(0,limit))container.append(textElement('div',issueMessage(i),`issue-row ${i.severity||i.level||''}`));if(issues?.length>limit)container.append(textElement('div',`另有 ${issues.length-limit} 项，请查看导出报告。`,'issue-row'));}
function previewOperation(){const record=!hasDraftChanges()?state.geometryRecords?.[state.current]:null;state.preview=null;const messages=record?[{message:`已整理：${record.paths.length} 组路径/轮廓 · ${record.status==='READY'?'几何已记录':'需要确认'}`},...(record.issues||[]).map(message=>({message}))]:[{message:'标注阶段仅保留来源；请在整图解释完成后点击“整理几何”。'}];renderIssues($('preview-issues'),messages,12);renderOverlays();}

function schedulePreview(){previewOperation();schedulePairing();}

function collectIssues(report){if(Array.isArray(report))return report;const list=report?.issues||report?.violations||[...(report?.errors||[]).map(i=>typeof i==='string'?{message:i,severity:'error'}:{...i,severity:'error'}),...(report?.warnings||[]).map(i=>typeof i==='string'?{message:i,severity:'warning'}:{...i,severity:'warning'})];return Array.isArray(list)?list:Object.entries(list).map(([code,message])=>({code,message:String(message)}));}
function pairingKey(project){return JSON.stringify(project.operations.map(op=>[op.uid,op.operation_id,op.operation_type,op.cad_parent_operation_id,op.process_group_id,op.process_group_source,op.process_group_pair_uids]));}
function copyPairingFields(operation,assignment){operation.process_group_id=assignment.process_group_id||null;for(const key of ['process_group_source','process_group_pair_uids']){if(assignment[key])operation[key]=clone(assignment[key]);else delete operation[key];}}
function renderPairingHint(){const op=state.draft;if(!op)return;const paired=['PRE_PUNCH','FLANGING'].includes(op.operation_type);const entry=state.pairingDraft?.uid===op.uid&&state.pairingDraft.key===pairingKey(temporaryProject())?state.pairingDraft.entry:null;$('pairing-help').textContent=entry?.message||(paired?'根据明确 CAD 父子关系自动配对；对应动作尚未录入或关系不唯一时会提示待确认。':'加工组仅用于预孔与翻孔配对，由脚本自动填写。');}
async function refreshPairing(){
  if(!state.draft||!['PRE_PUNCH','FLANGING'].includes(state.draft.operation_type)){renderPairingHint();return;}
  const project=temporaryProject(),key=pairingKey(project),uid=state.draft.uid;
  try{const result=await request('/api/pairing',{project});if(uid!==state.draft.uid||key!==pairingKey(temporaryProject()))return;const clean=!hasDraftChanges(),assignment=result.assignments.find(item=>item.uid===uid);if(assignment)copyPairingFields(state.draft,assignment);if(clean)state.draftBase=JSON.stringify(state.draft);state.pairingDraft={uid,key:pairingKey(temporaryProject()),entry:result.statuses[uid]};$('process-group').value=state.draft.process_group_id||'';renderPairingHint();updateDirty();}catch(error){if(uid===state.draft?.uid&&key===pairingKey(temporaryProject()))$('pairing-help').textContent=`自动配对暂未完成：${error.message}`;}
}
function schedulePairing(){clearTimeout(previewTimer);previewTimer=setTimeout(()=>refreshPairing(),180);}
function applyProjectPairing(result){
  if(!result)return;const clean=!hasDraftChanges(),stored=state.project.operations.find(op=>op.uid===state.draft?.uid);const draftMatches=stored&&['operation_id','operation_type','cad_parent_operation_id'].every(key=>stored[key]===state.draft[key]);
  for(const assignment of result.assignments||[]){const operation=state.project.operations.find(op=>op.uid===assignment.uid);if(operation)copyPairingFields(operation,assignment);if(draftMatches&&assignment.uid===state.draft.uid)copyPairingFields(state.draft,assignment);}
  if(draftMatches){if(clean)state.draftBase=JSON.stringify(state.draft);state.pairingDraft={uid:state.draft.uid,key:pairingKey(temporaryProject()),entry:result.statuses[state.draft.uid]};$('process-group').value=state.draft.process_group_id||'';}renderPairingHint();updateDirty();
}
async function validate(show=false){const seq=state.validateSerial=(state.validateSerial||0)+1,submitted=fingerprint();try{const result=await request('/api/validate',{project:state.project});if(seq!==state.validateSerial||submitted!==fingerprint())return result;applyProjectPairing(result.report?.pairing);state.statuses=result.statuses||{};state.statistics=result.statistics||{};state.geometries=result.geometries||{};state.regions=result.regions||[];state.geometryRecords=result.report?.geometry_records||{};state.geometryState=result.report?.geometry_state;renderSelection();renderStatistics();if(show)showReport(result.report||result,'数据检查');return result;}catch(e){if(show)toast(e.message,true);return null;}}

function scheduleValidate(){clearTimeout(validateTimer);validateTimer=setTimeout(()=>validate(),180);}
function showReport(report,title='检查结果'){const panel=$('report-panel'),content=$('report-content');panel.hidden=false;$('report-title').textContent=title;content.replaceChildren();const ready=report.ready===true||report.status==='ready';content.append(textElement('div',ready?(report.data_contract?.status==='PASSED'&&report.hard_feasibility?.feasible===true?'数据契约与 H1–H7 检查通过，可使用正式数据包。':'标注完整性检查通过；正式导出将继续检查数据契约与 H1–H7。'):'项目仍为草稿，请根据以下检查项补齐。',`report-state${ready?' ready':''}`));const issues=collectIssues(report),holder=document.createElement('div');renderIssues(holder,issues);content.append(holder);if(report.geometry_records){const labels={READY:'几何已记录',NEEDS_CONFIRMATION:'待核对',NEEDS_REVIEW:'检查绑定',RULE_PENDING:'规则待定'};for(const record of Object.values(report.geometry_records))content.append(textElement('div',`${record.operation_id} · ${labels[record.status]||record.status} · ${record.paths?.length||0} 组路径/轮廓${record.legacy_supported?'':' · 旧表适配待定'}`,'issue-row'));}if(!issues.length&&!ready)content.append(textElement('p',report.message||'请查看工序配置、动作清单确认及几何覆盖状态。','issue-row'));$('export-links').replaceChildren();}
async function saveProject(){if(state.busy)return;if(hasDraftChanges()&&!applyOperation(false))return;state.busy=true;$('save-project').disabled=true;try{const result=await request('/api/save',{project:state.project,expected_revision:state.revision});state.project=result.project;state.revision=state.project.revision;state.saved=fingerprint();if(state.current){const op=state.project.operations.find(o=>o.uid===state.current);if(op){state.draft=clone(op);state.draftBase=JSON.stringify(op);}}renderProject();await validate();toast(`进度已写入本地项目文件 · 修订 ${state.revision}`);}catch(e){toast(`保存失败：${e.message}`,true);}finally{state.busy=false;$('save-project').disabled=false;updateDirty();}}
async function reloadProject(){if(isDirty()&&!await ask('重新读取将放弃尚未保存的项目和动作修改，继续？'))return;try{const r=await request('/api/project');state.project=r.project;state.revision=state.project.revision||0;state.saved=fingerprint();state.history=[];state.redo=[];setDraft(defaultOperation());renderProject();await validate();toast('已从本地项目文件重新读取。');}catch(e){toast(e.message,true);}}
function downloadBackup(){if(hasDraftChanges()&&!applyOperation(false))return;const blob=new Blob([JSON.stringify(state.project,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${state.project.part_id}_annotation_revision${state.revision}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('项目备份已提交浏览器下载；可使用“导入项目 JSON”恢复。');}
async function importProject(file){try{const p=JSON.parse(await file.text());if(!Array.isArray(p.operations)||!p.part_id)throw new Error('不是有效的标注项目。');if(p.source_sha256&&p.source_sha256!==state.drawing.source.sha256)throw new Error('源 DXF 指纹不一致，不能自动重新绑定。');if(isDirty()&&!await ask('导入会替换当前未保存内容，继续？'))return;checkpoint();p.source_sha256=state.drawing.source.sha256;p.revision=state.revision;state.project=(await request('/api/normalize_project',{project:p})).project;setDraft(defaultOperation());renderProject();await validate();toast('已导入备份；请保存进度以写入当前项目。');}catch(e){toast(`导入失败：${e.message}`,true);}}
function fileBase64(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('文件读取失败'));reader.readAsDataURL(file);});}
async function importWorkbook(file){try{const r=await request('/api/import_workbook',{filename:file.name,base64:await fileBase64(file)});checkpoint();state.project.station_rows=r.station_rows;state.project.fixed_rows=r.fixed_rows;state.project.sheet4_confirmed=r.sheet4_confirmed;state.project.station_import_source={...r.station_import_source,filename:file.name};renderStatistics();updateDirty();scheduleValidate();toast(`已导入 ${r.station_rows.length} 道工序及 ${r.fixed_rows.length} 条固定分配。`);}catch(e){toast(e.message,true);}}
async function importOperations(file){
  try{
    const r=await request('/api/import_operations',{filename:file.name,base64:await fileBase64(file)});
    const existing=new Set(state.project.operations.map(o=>o.operation_id));
    const conflicts=r.operations.filter(o=>existing.has(o.operation_id)).map(o=>o.operation_id);
    if(conflicts.length)throw new Error(`以下编号已存在，未覆盖已有动作：${conflicts.slice(0,12).join('、')}${conflicts.length>12?'…':''}`);
    if(hasDraftChanges()&&!await ask('导入将保留已创建动作，并放弃当前尚未应用的编辑，继续？'))return;
    checkpoint();
    for(const op of r.operations)state.project.operations.push({...defaultOperation(),...op,source_segment_ids:[],geometry_options:{confirmed_span:false,confirmed_footprint:false}});
    state.project.inventory_confirmed=false;
    state.project.operation_import_sources ||= [];
    state.project.operation_import_sources.push({filename:file.name,count:r.operations.length,imported_at:new Date().toISOString()});
    setDraft(defaultOperation());renderProject();await validate();
    toast(`已导入 ${r.operations.length} 个待绑定动作；仅保留显式父子/前置关系，表格行序不转成工艺顺序。`);
  }catch(e){toast(`动作清单导入失败：${e.message}`,true);}
}
async function compileGeometry(){
  if(hasDraftChanges()&&!applyOperation(false))return;
  if(!state.project.inventory_confirmed){toast('请先完成整图动作解释，再勾选“整图动作解释完成”。',true);return;}
  $('compile-geometry').disabled=true;
  try{const result=await request('/api/compile_geometry',{project:state.project});checkpoint();state.project=result.project;state.geometryRecords=result.report.geometry_records||{};state.geometries=result.report.geometries||{};state.regions=result.report.regions||[];state.geometryState=result.report.geometry_state;renderProject();previewOperation();showReport(result.report,'几何整理结果');toast('已按动作类型统一整理；检查结果后保存标注。');}catch(e){toast(`整理未完成：${e.message}`,true);}finally{$('compile-geometry').disabled=false;}
}
async function exportProject(mode){if(hasDraftChanges()&&!applyOperation(false))return;try{const r=await request('/api/export',{project:state.project,mode});showReport(r.report||{},mode==='draft'?'草稿导出':'校验后导出');for(const f of r.files||[]){const a=document.createElement('a');a.textContent=f.name;a.href=f.url;a.download=f.name;$('export-links').append(a);}toast(r.files?.length?'导出文件已生成，点击检查区中的链接下载。':'尚未生成正式数据，请先解决检查项。',!r.files?.length);}catch(e){toast(`导出失败：${e.message}`,true);}}
async function markIgnored(){if(!state.selected.size){toast('请先选择需要标记的实体。');return;}const reason=await ask('背景 / 忽略原因：',{input:true,initial:'仅用于图纸结构参考'});if(!reason?.trim())return;checkpoint();state.project.ignored_entities ||= {};for(const id of state.selected)state.project.ignored_entities[id]=reason.trim();scheduleValidate();updateDirty();toast('已记录背景标记，直接绑定的实体仍优先计为绑定。');}
function restoreIgnored(){if(!state.selected.size)return;checkpoint();for(const id of state.selected)delete state.project.ignored_entities[id];scheduleValidate();updateDirty();toast('已移除所选实体的背景标记；其它有效绑定仍会保留。');}
function excludeAbsorption(){if(!state.selected.size)return;checkpoint();for(const op of state.project.operations){if(op.operation_type==='BRIDGE')op.absorption_exclusions=[...new Set([...(op.absorption_exclusions||[]),...state.selected])];}if(state.current){const updated=state.project.operations.find(o=>o.uid===state.current);if(updated){state.draft.absorption_exclusions=clone(updated.absorption_exclusions||[]);state.draftBase=JSON.stringify(updated);}}scheduleValidate();updateDirty();toast('所选实体已从现有折桥区域收纳中排除。');}

function initializeControls(){
  $('operation-form').addEventListener('submit',e=>{e.preventDefault();applyOperation(true,{advanceAfterCreate:true});});$('new-operation').onclick=newOperation;$('delete-operation').onclick=deleteOperation;$('save-project').onclick=saveProject;$('compile-geometry').onclick=compileGeometry;$('reload-project').onclick=reloadProject;$('backup-project').onclick=downloadBackup;$('import-project').onclick=()=>$('project-file').click();$('import-workbook').onclick=()=>$('workbook-file').click();$('import-operations').onclick=()=>$('operations-file').click();$('operations-file').onchange=e=>{if(e.target.files[0])importOperations(e.target.files[0]);e.target.value='';};$('project-file').onchange=e=>{if(e.target.files[0])importProject(e.target.files[0]);e.target.value='';};$('workbook-file').onchange=e=>{if(e.target.files[0])importWorkbook(e.target.files[0]);e.target.value='';};$('undo').onclick=undo;$('redo').onclick=redo;$('validate-project').onclick=()=>{if(hasDraftChanges()&&!applyOperation(false))return;validate(true);};$('export-draft').onclick=()=>exportProject('draft');$('export-validated').onclick=()=>exportProject('validated');$('close-report').onclick=()=>$('report-panel').hidden=true;
  $('operation-search').oninput=renderList;$('operation-filter').onchange=renderList;$('clear-selection').onclick=()=>setSelection([]);$('fit-all').onclick=fitAll;$('fit-current').onclick=fitCurrent;$('view-source').onclick=fitCurrent;$('ignore-selection').onclick=markIgnored;$('restore-selection').onclick=restoreIgnored;$('exclude-absorption').onclick=excludeAbsorption;
  $('expand-group').onclick=()=>{const groups=new Set([...state.selected].map(id=>segments.get(id)?.source_group).filter(Boolean));if(!groups.size){toast('请先选中一个具有原始来源的子段。');return;}setSelection([...segments.values()].filter(s=>groups.has(s.source_group)).map(s=>s.id),true);};
  for(const b of document.querySelectorAll('[data-tool]'))b.onclick=()=>{state.tool=b.dataset.tool;for(const item of document.querySelectorAll('[data-tool]'))item.classList.toggle('active',item===b);$('drawing').classList.toggle('pan-tool',state.tool==='pan');};
  $('orientation').onchange=()=>{state.orientation=$('orientation').value;setTransform();fitAll();};$('show-annotations').onchange=renderAnnotations;$('show-regions').onchange=renderOverlays;$('only-unhandled').onchange=()=>$('source-layer').classList.toggle('highlight-unhandled',$('only-unhandled').checked);$('show-background').onchange=()=>$('source-layer').classList.toggle('hide-background',!$('show-background').checked);
  for(const id of ['part-id','expected-count','inventory-confirmed'])$(id).addEventListener('change',()=>{checkpoint();state.project.part_id=$('part-id').value.trim();state.project.expected_operation_count=$('expected-count').value===''?null:Number($('expected-count').value);state.project.inventory_confirmed=$('inventory-confirmed').checked;updateDirty();scheduleValidate();});
  $('operation-form').addEventListener('focusin',()=>{if(!state.formBefore)state.formBefore=snapshot();});
  $('operation-form').addEventListener('change',e=>{
    if(!state.draft)return;
    const before=state.formBefore||snapshot(),old=before.draft||clone(state.draft);
    state.history.push(before);if(state.history.length>70)state.history.shift();state.redo=[];state.formBefore=null;
    readForm();
    if(e.target.id==='operation-type'&&old.feature_type!==state.draft.feature_type){invalidateGeometry();}
    if(e.target.id==='shared-confirmed'){state.draft.shared_source_segment_ids=e.target.checked?[...state.selected]:[];}
    if(e.target.id==='no-geometry'&&state.draft.no_geometry&&state.selected.size){state.draft.no_geometry=false;toast('请先清空已选图元，再确认无适用几何。',true);}
    if(['affected-side','far-boundary','region-id'].includes(e.target.id)&&state.draft.region)state.draft.region.confirmed=false;
    if(e.target.id==='parent-region'&&state.draft.region){state.draft.region.parent_confirmed=false;state.draft.region.confirmed=false;}
    if(e.target.id==='region-enabled'&&state.draft.region&&!old.region)state.draft.region.influence_region_id=`R_${state.draft.operation_id||'NEW'}`;
    renderEditor();renderSelection();schedulePreview();updateDirty();
  });
  $('operation-form').addEventListener('input',e=>{if(!state.formBefore)state.formBefore=snapshot();readForm();if(['operation-id','cad-parent'].includes(e.target.id))schedulePairing();if(e.target.id==='cad-parent')renderSelection();updateDirty();});
  window.addEventListener('keydown',e=>{const typing=/^(INPUT|TEXTAREA|SELECT)$/.test(document.activeElement?.tagName);if(!typing&&e.code==='Space'){spaceDown=true;$('drawing').classList.add('pan-tool');e.preventDefault();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();}if(!typing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();}if(!typing&&(e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();redo();}if(!typing&&e.key==='Escape'){$('hit-picker').hidden=true;}});window.addEventListener('keyup',e=>{if(e.code==='Space'){spaceDown=false;$('drawing').classList.toggle('pan-tool',state.tool==='pan');}});window.addEventListener('blur',()=>{spaceDown=false;drag=null;});window.addEventListener('beforeunload',e=>{if(isDirty()){e.preventDefault();e.returnValue='';}});
  new ResizeObserver(()=>{const rect=$('drawing').getBoundingClientRect();if(state.view&&rect.height>0){const cx=state.view[0]+state.view[2]/2,cy=state.view[1]+state.view[3]/2,w=state.view[2],h=w*rect.height/rect.width;state.view=[cx-w/2,cy-h/2,w,h];applyView();}const top=$('app-header')?.offsetHeight||document.querySelector('.app-header').offsetHeight,bar=document.querySelector('.project-bar').offsetHeight;document.querySelector('.workspace').style.height=`calc(100vh - ${top+bar}px)`;}).observe($('canvas-wrap'));
}
async function bootstrap(){try{const data=await request('/api/bootstrap');state.fieldDefaults=data.field_defaults||{};state.drawing=data.drawing;state.project=data.project;state.project.workflow_version=2;state.project.operations ||= [];state.project.ignored_entities ||= {};state.project.source_sha256 ||= state.drawing.source.sha256;state.revision=state.project.revision||0;state.saved=fingerprint();$('source-label').textContent=`${state.drawing.source.file_name} · ${state.drawing.source.units||'源单位'} · ${state.drawing.segments.length.toLocaleString()} 个几何片段 · 仅本地运行`;$('operation-type').replaceChildren(new Option('请选择',''));featureTypes=data.feature_types||[];for(const type of featureTypes)$('operation-type').add(new Option(type.label,type.key));for(const type of featureTypes)$('operation-filter').add(new Option(type.label,type.key));$('surface-side').replaceChildren(new Option('请选择表面侧',''));for(const side of data.surface_sides||['UNKNOWN','SMOOTH','ROUGH'])$('surface-side').add(new Option(({SMOOTH:'光面 SMOOTH',ROUGH:'毛面 ROUGH',UNKNOWN:'未指定 UNKNOWN',NA:'不适用 NA',NOT_APPLICABLE:'不适用'})[side]||side,side));state.orientation=String(state.drawing.config.default_rotation??270);$('orientation').value=state.orientation;initializeDrawing();state.draft=defaultOperation();state.draftBase=JSON.stringify(state.draft);initializeControls();initializeCanvasEvents();renderProject();await validate();if(state.drawing.issues?.length)toast(`DXF 读取完成，含 ${state.drawing.issues.length} 条解析提示，请查看检查结果。`);}catch(e){$('empty-canvas').textContent=`加载失败：${e.message}`;$('source-label').textContent='无法连接本地服务';$('save-status').textContent='连接失败';toast(e.message,true);}}
